import sys
import math
import random

# Since Python doesn't have a built-in hash table with custom hash functions like __gnu_pbds,
# we will use a standard dictionary for possible_states.
# The custom hash function is not directly translatable, but for the purpose of this translation,
# we will ignore it and use default hashing.

# Helper functions
def get_random_address():
    p = bytearray(random.getrandbits(8) for _ in range(8))
    return int.from_bytes(p, byteorder='little')

def splitmix64(x):
    x += 0x9e3779b97f4a7c15
    x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9
    x = (x ^ (x >> 27)) * 0x94d049bb133111eb
    return x ^ (x >> 31)

# Modular class
MOD_CONST = 10**9 + 7

class Modular:
    def __init__(self, v=0):
        if v < 0:
            v %= MOD_CONST
        self.value = v % MOD_CONST

    @staticmethod
    def extended_gcd(a, m):
        if m == 0:
            return a, 1, 0
        g, y, x = Modular.extended_gcd(m, a % m)
        y -= (a // m) * x
        return g, x, y

    @staticmethod
    def modular_inverse(a, m=MOD_CONST):
        g, x, y = Modular.extended_gcd(a, m)
        return x % m

    def __add__(self, other):
        return Modular(self.value + other.value)

    def __sub__(self, other):
        return Modular(self.value - other.value)

    def __mul__(self, other):
        return Modular((self.value * other.value) % MOD_CONST)

    def __truediv__(self, other):
        inv = Modular.modular_inverse(other.value)
        return Modular((self.value * inv) % MOD_CONST)

    def __iadd__(self, other):
        self.value += other.value
        if self.value >= MOD_CONST:
            self.value -= MOD_CONST
        return self

    def __isub__(self, other):
        self.value -= other.value
        if self.value < 0:
            self.value += MOD_CONST
        return self

    def __imul__(self, other):
        self.value = (self.value * other.value) % MOD_CONST
        return self

    def __itruediv__(self, other):
        self.value = (self.value * Modular.modular_inverse(other.value)) % MOD_CONST
        return self

    def __eq__(self, other):
        return self.value == other.value

    def __ne__(self, other):
        return self.value != other.value

    def __neg__(self):
        return Modular(0) if self.value == 0 else Modular(MOD_CONST - self.value)

    def pow(self, p):
        assert p >= 0
        result = Modular(1)
        base = Modular(self.value)
        while p > 0:
            if p & 1:
                result *= base
            base *= base
            p >>= 1
        return result

    def __int__(self):
        return self.value

# Read input
size_N = int(sys.stdin.readline())

prob_matrix = [[Modular(int(sys.stdin.readline())) / Modular(100) for _ in range(size_N)] for _ in range(size_N)]

# Precompute count_masks and lookup_mask
count_masks = [[] for _ in range(size_N + 1)]
lookup_mask = [-1] * (1 << size_N)
for mask in range(1 << size_N):
    c = bin(mask).count('1')
    lookup_mask[mask] = len(count_masks[c])
    count_masks[c].append(mask)

# Initialize possible_states
possible_states = {1 << lookup_mask[0]: Modular(1)}

for left in range(size_N):
    new_states = {}
    product_mask = [Modular(1) for _ in range(1 << size_N)]
    for current_mask in range(1 << size_N):
        prod = Modular(1)
        for right in range(size_N):
            if (current_mask >> right) & 1:
                prod *= prob_matrix[left][right]
            else:
                prod *= Modular(1) - prob_matrix[left][right]
        product_mask[current_mask] = prod

    new_bits = [0] * size_N
    new_possible = [Modular(0) for _ in range(1 << size_N)]
    for state_mask, prob_value in possible_states.items():
        mask_state = state_mask
        # Reset new_bits
        for i in range(size_N):
            new_bits[i] = 0
        for mask in count_masks[left]:
            if (mask_state >> lookup_mask[mask]) & 1:
                for i in range(size_N):
                    if ((mask >> i) & 1) == 0:
                        new_bits[i] |= 1 << lookup_mask[mask | (1 << i)]
        for current_mask in range(1, 1 << size_N):
            # __builtin_ctz in Python
            def ctz(x):
                return (x & -x).bit_length() - 1
            new_possible[current_mask] = new_possible[current_mask & (current_mask - 1)] | new_bits[ctz(current_mask)]
            new_states[new_possible[current_mask]] = new_states.get(new_possible[current_mask], Modular(0)) + prob_value * product_mask[current_mask]
    possible_states = new_states

# Sum over states
answer = Modular(0)
for state_mask, prob_value in possible_states.items():
    if (state_mask >> lookup_mask[(1 << size_N) - 1]) & 1:
        answer += prob_value

print(int(answer))
